{% if is_incremental() %}

SELECT
  arriving.reject_id,
  arriving.source_relation,
  arriving.mapping,
  arriving.mapping_version,
  arriving.failed_rules,
  arriving.key_values,
  arriving.raw,
  arriving._load_id,
  arriving._ingested_at,
  arriving._source_row_id,
  COALESCE(incumbent.first_seen, arriving.first_seen) AS first_seen,
  arriving.last_seen,
  arriving.resolved_at,
  COALESCE(incumbent.last_evaluated_at, arriving.last_evaluated_at) AS last_evaluated_at
FROM (
  SELECT
    _extract.reject_id,
    _extract.source_relation,
    _extract.mapping,
    _extract.mapping_version,
    ARRAY_CAT(
      ARRAY_CAT(
        ARRAY_CAT(
          ARRAY_CAT(
            ARRAY_CAT(
              ARRAY_CAT(
                CASE
                  WHEN _extract._branch_code_fail_coercible
                  THEN ARRAY['code_fail_coercible']
                  ELSE CAST(ARRAY[] AS TEXT[])
                END,
                CASE
                  WHEN _extract._win_code_fail_unique
                  THEN ARRAY['code_fail_unique']
                  ELSE CAST(ARRAY[] AS TEXT[])
                END
              ),
              CASE
                WHEN _extract._branch_code_flag_coercible
                THEN ARRAY['code_flag_coercible']
                ELSE CAST(ARRAY[] AS TEXT[])
              END
            ),
            CASE
              WHEN _extract._win_code_flag_unique
              THEN ARRAY['code_flag_unique']
              ELSE CAST(ARRAY[] AS TEXT[])
            END
          ),
          CASE
            WHEN _extract._branch_code_id_coercible
            THEN ARRAY['code_id_coercible']
            ELSE CAST(ARRAY[] AS TEXT[])
          END
        ),
        CASE
          WHEN _extract._branch_code_quar_coercible
          THEN ARRAY['code_quar_coercible']
          ELSE CAST(ARRAY[] AS TEXT[])
        END
      ),
      CASE
        WHEN _extract._win_code_quar_unique
        THEN ARRAY['code_quar_unique']
        ELSE CAST(ARRAY[] AS TEXT[])
      END
    ) AS failed_rules,
    JSON_BUILD_OBJECT('code_id', _extract.code_id) AS key_values,
    _extract._raw AS raw,
    _extract._load_id,
    _extract._ingested_at,
    _extract._source_row_id,
    _extract._ingested_at AS first_seen,
    _extract._ingested_at AS last_seen,
    CAST(NULL AS TIMESTAMP) AS resolved_at,
    CAST(NULL AS TIMESTAMP) AS last_evaluated_at
  FROM (
    SELECT
      *,
      (
        COUNT(*) OVER (PARTITION BY code_fail) > 1 AND (
          NOT code_fail IS NULL
        )
      ) AS _win_code_fail_unique,
      (
        COUNT(*) OVER (PARTITION BY code_flag) > 1 AND (
          NOT code_flag IS NULL
        )
      ) AS _win_code_flag_unique,
      (
        COUNT(*) OVER (PARTITION BY code_quar) > 1 AND (
          NOT code_quar IS NULL
        )
      ) AS _win_code_quar_unique
    FROM (
      SELECT
        CASE WHEN PG_INPUT_IS_VALID(code_fail, 'TEXT') THEN CAST(code_fail AS TEXT) END AS code_fail,
        CASE WHEN PG_INPUT_IS_VALID(code_flag, 'TEXT') THEN CAST(code_flag AS TEXT) END AS code_flag,
        CASE WHEN PG_INPUT_IS_VALID(code_id, 'TEXT') THEN CAST(code_id AS TEXT) END AS code_id,
        CASE WHEN PG_INPUT_IS_VALID(code_quar, 'TEXT') THEN CAST(code_quar AS TEXT) END AS code_quar,
        _ingested_at,
        _load_id,
        _source_row_id,
        CASE WHEN PG_INPUT_IS_VALID(code_fail, 'TEXT') THEN CAST(code_fail AS TEXT) END IS NULL
        AND (
          NOT code_fail IS NULL
        ) AS _branch_code_fail_coercible,
        CASE WHEN PG_INPUT_IS_VALID(code_flag, 'TEXT') THEN CAST(code_flag AS TEXT) END IS NULL
        AND (
          NOT code_flag IS NULL
        ) AS _branch_code_flag_coercible,
        CASE WHEN PG_INPUT_IS_VALID(code_id, 'TEXT') THEN CAST(code_id AS TEXT) END IS NULL
        AND (
          NOT code_id IS NULL
        ) AS _branch_code_id_coercible,
        CASE WHEN PG_INPUT_IS_VALID(code_quar, 'TEXT') THEN CAST(code_quar AS TEXT) END IS NULL
        AND (
          NOT code_quar IS NULL
        ) AS _branch_code_quar_coercible,
        JSON_BUILD_OBJECT(
          '_ingested_at',
          _ingested_at,
          '_load_id',
          _load_id,
          '_source_row_id',
          _source_row_id,
          'code_fail',
          code_fail,
          'code_flag',
          code_flag,
          'code_id',
          code_id,
          'code_quar',
          code_quar
        ) AS _raw,
        ENCODE(
          SHA256(
            CONVERT_TO(
              'S8:q__codes' || 'S' || CAST(LENGTH(_source_row_id) AS TEXT) || ':' || _source_row_id,
              'UTF8'
            )
          ),
          'hex'
        ) AS reject_id,
        'q__codes' AS source_relation,
        'q__codes->q_code' AS mapping,
        1 AS mapping_version
      FROM {{ source('bronze', 'q__codes') }}
    ) AS _deduped
  ) AS _extract
  WHERE
    COALESCE(
      (
        _extract._branch_code_fail_coercible
        OR _extract._branch_code_flag_coercible
        OR _extract._branch_code_id_coercible
        OR _extract._branch_code_quar_coercible
        OR _extract._win_code_quar_unique
      ),
      FALSE
    )
) AS arriving
LEFT JOIN {{ this }} AS incumbent
  ON arriving.reject_id = incumbent.reject_id

